std::vector<int> nums = {1, 2, 3, 4, 5};

// Type definition for brevity
using IntOut = std::ostream_iterator<int>;

// Output iterator targeting std::cout with a space delimiter
IntOut out_it(std::cout, " ");

// Write the range using std::copy
std::copy(nums.begin(), nums.end(), out_it);

// Output: 1 2 3 4 5
std::cout << "\n";
